mapper.select:
SELECT x.* FROM () x x.status = #{status} ORDER BY
x.priority_rank ASC x.checked_at DESC, x.saved_at DESC x.score DESC, x.saved_at DESC
LIMIT #{size} OFFSET #{offset}

mapper.delete:
DELETE f FROM vulnerability_factor f
  JOIN vulnerability_list l ON l.vulnerability_id = f.vulnerability_id
 WHERE l.user_id = #{userId}
   AND f.factor_id IN #{id}
   AND NOT EXISTS (SELECT 1 FROM survey_plan sp WHERE sp.factor_id = f.factor_id)
